	private string getActionOwner(ClipboardContentProviderService clipboardService) {
		string owner = clipboardService.getClipboardActionOwner();
		if (owner != null) {
			return owner;
		}
		return getName();
	}

	private class CopyAction : DockingAction, ICopy {
		private ClipboardContentProviderService clipboardService;

		private CopyAction(ClipboardContentProviderService clipboardService) : base("Copy", getActionOwner(clipboardService))
    {
			this.clipboardService = clipboardService;

			setPopupMenuData(new MenuData(new string[] { "Copy" }, "Clipboard"));
			setToolBarData(new ToolBarData(new GIcon("icon.plugin.clipboard.copy"),
				"Clipboard"));
			setKeyBindingData(
				new KeyBindingData(KeyEvent.VK_C, DockingUtils.CONTROL_KEY_MODIFIER_MASK));
			setHelpLocation(new HelpLocation("ClipboardPlugin", "Copy"));
			clipboardService.customizeClipboardAction(this);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			copy(clipboardService);
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			if (!clipboardService.isValidContext(context)) {
				return false;
			}
			return clipboardService.canCopy();
		}

		/* @Override */
		public bool isAddToPopup(ActionContext context) {
			return context is ListingActionContext || isEnabledForContext(context);
		}
	}

	private class PasteAction : DockingAction, IPaste {
		private ClipboardContentProviderService clipboardService;

		private PasteAction(ClipboardContentProviderService clipboardService) : base("Paste", this.getActionOwner(clipboardService))
    {
			this.clipboardService = clipboardService;

			setPopupMenuData(new MenuData(new string[] { "Paste" }, "Clipboard"));
			setToolBarData(
				new ToolBarData(new GIcon("icon.plugin.clipboard.paste"), "Clipboard"));
			setKeyBindingData(
				new KeyBindingData(KeyEvent.VK_V, DockingUtils.CONTROL_KEY_MODIFIER_MASK));
			setHelpLocation(new HelpLocation("ClipboardPlugin", "Paste"));
			clipboardService.customizeClipboardAction(this);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			paste(clipboardService);
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			if (!clipboardService.isValidContext(context)) {
				return false;
			}

			Clipboard systemClipboard = getSystemClipboard();
			DataFlavor[] flavors = getAvailableDataFlavors(systemClipboard);
			return clipboardService.canPaste(flavors);
		}

		/* @Override */
		public bool isAddToPopup(ActionContext context) {
			return context is ListingActionContext || isEnabledForContext(context);
		}
	}

	private class CopySpecialAction : DockingAction, ICopy {
		private ClipboardContentProviderService clipboardService;

		private CopySpecialAction(ClipboardContentProviderService clipboardService) : base("Copy Special", this.getActionOwner(clipboardService))
    {
