	private static class PasteTask : Task {

		private Clipboard clipboard;
		private ClipboardContentProviderService clipboardService;

		public PasteTask(Clipboard clipboard, ClipboardContentProviderService clipboardService) : base("Paste Task", false, false, true)
    {
			this.clipboard = clipboard;
			this.clipboardService = clipboardService;
		}

		/* @Override */
		public void run(TaskMonitor monitor) {
			Transferable transferable = clipboard.getContents(this);
			clipboardService.paste(transferable);
		}

	}

	internal class _Anon_Task_1 : Task
	{
		public _Anon_Task_1() : @base("Copying", true, false, true) {}

			/* @Override */
			public void run(TaskMonitor monitor) {
				monitor.setMessage("Setting Clipboard Contents");
				Clipboard systemClipboard = getSystemClipboard();
				Transferable transferable = clipboardService.copy(monitor);
				if (removeQuotes && transferable is StringTransferable stringTransferable) {
					stringTransferable.removeOuterQuotesAndStandardStringPrefix();
				}

				if (transferable == null) {
					return;
				}
				if (clipboardOwnerProvider != null) {
					clipboardOwnerProvider.lostOwnership(null);
				}

				setClipboardContents(systemClipboard, transferable);
				clipboardOwnerProvider = clipboardService;
				updatePasteState();
			}
		
	}


	internal class _Anon_Task_2 : Task
	{
		public _Anon_Task_2() : @base("Copying", true, false, true) {}

			/* @Override */
			public void run(TaskMonitor monitor) {
				monitor.setMessage("Setting Clipboard Contents");

				Clipboard systemClipboard = getSystemClipboard();
				Transferable transferable = clipboardService.copySpecial(selectedType, monitor);
				if (transferable != null) {
					setClipboardContents(systemClipboard, transferable);
					clipboardOwnerProvider = clipboardService;
					updatePasteState();
				}
			}
		
	}

